function check(candidate) {
    console.assert(JSON.stringify(candidate([1,1,1,1,1,1,1], 1)) === JSON.stringify([0, 6]));
    console.assert(JSON.stringify(candidate([2,2,2,2,3,3,4,4,4,4], 2)) === JSON.stringify([0, 3]));
    console.assert(JSON.stringify(candidate([1,2,3,4,5], 5)) === JSON.stringify([4, 4]));
    console.assert(JSON.stringify(candidate([5,7,7,8,8,10], 8)) === JSON.stringify([3, 4]));
    console.assert(JSON.stringify(candidate([1,2,3,4,5,6,7], 1)) === JSON.stringify([0, 0]));
    console.assert(JSON.stringify(candidate([-10,-5,-3,0,3,5,9,10], 3)) === JSON.stringify([4, 4]));
